// Clustering, distances, mixtures and principal components.
import { mean, sum } from './stats.js';

export const d2 = (a, b) => { let s = 0; for (let i = 0; i < a.length; i++) { const d = a[i] - b[i]; s += d * d; } return s; };
export const euclid = (a, b) => Math.sqrt(d2(a, b));
export const manhattan = (a, b) => a.reduce((s, v, i) => s + Math.abs(v - b[i]), 0);
export const minkowski = (a, b, p) => (p === Infinity ? Math.max(...a.map((v, i) => Math.abs(v - b[i]))) : Math.pow(a.reduce((s, v, i) => s + Math.abs(v - b[i]) ** p, 0), 1 / p));
export function cosine(a, b) { let d = 0, x = 0, y = 0; for (let i = 0; i < a.length; i++) { d += a[i] * b[i]; x += a[i] * a[i]; y += b[i] * b[i]; } return x && y ? d / Math.sqrt(x * y) : 0; }
export const hamming = (a, b) => { let d = 0; for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) d++; return d; };
export function jaccard(a, b) { const A = new Set(a), B = new Set(b); let i = 0; for (const x of A) if (B.has(x)) i++; const u = A.size + B.size - i; return u ? i / u : 1; }
export function levenshtein(a, b) { const m = a.length, n = b.length, d = Array.from({ length: m + 1 }, (_, i) => [i, ...new Array(n).fill(0)]); for (let j = 0; j <= n; j++) d[0][j] = j; for (let i = 1; i <= m; i++) for (let j = 1; j <= n; j++) d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)); return d[m][n]; }
export function dtw(a, b) { const n = a.length, m = b.length, D = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(Infinity)); D[0][0] = 0; for (let i = 1; i <= n; i++) for (let j = 1; j <= m; j++) D[i][j] = Math.abs(a[i - 1] - b[j - 1]) + Math.min(D[i - 1][j], D[i][j - 1], D[i - 1][j - 1]); return D[n][m]; }
export function mahalanobis(p, mu, cov) { const dx = p[0] - mu[0], dy = p[1] - mu[1], det = cov[0][0] * cov[1][1] - cov[0][1] * cov[1][0], a = cov[1][1] / det, b = -cov[0][1] / det, d = cov[0][0] / det; return Math.sqrt(dx * dx * a + 2 * dx * dy * b + dy * dy * d); }
export function knn(points, labels, q, k, dist = euclid) { const d = points.map((p, i) => [dist(p, q), i]).sort((a, b) => a[0] - b[0]).slice(0, k), votes = new Map(); for (const [, i] of d) votes.set(labels[i], (votes.get(labels[i]) || 0) + 1); let best = null, bc = -1; for (const [l, c] of votes) if (c > bc) { bc = c; best = l; } return { label: best, neighbours: d.map((x) => x[1]), votes }; }

// ---- k-means ----
export function assign(points, cents, dist = d2) { return points.map((p) => { let b = 0, bd = Infinity; for (let j = 0; j < cents.length; j++) { const d = dist(p, cents[j]); if (d < bd) { bd = d; b = j; } } return b; }); }
export function update(points, labels, k, old) { const dim = points[0].length, s = Array.from({ length: k }, () => new Array(dim).fill(0)), n = new Array(k).fill(0); points.forEach((p, i) => { n[labels[i]]++; for (let d = 0; d < dim; d++) s[labels[i]][d] += p[d]; }); return s.map((v, j) => (n[j] ? v.map((x) => x / n[j]) : old[j].slice())); }
export function inertia(points, labels, cents) { let s = 0; points.forEach((p, i) => { s += d2(p, cents[labels[i]]); }); return s; }
export function kmeans(points, init, maxIter = 100) { let cents = init.map((c) => c.slice()), labels = assign(points, cents), it = 0; const trace = [inertia(points, labels, cents)]; for (; it < maxIter; it++) { const nc = update(points, labels, cents.length, cents), nl = assign(points, nc); trace.push(inertia(points, nl, nc)); const same = nl.every((l, i) => l === labels[i]); cents = nc; labels = nl; if (same) break; } return { cents, labels, inertia: trace[trace.length - 1], trace, iters: it }; }
export function kmeanspp(points, k, rng) { const cents = [points[rng.int(0, points.length - 1)].slice()]; while (cents.length < k) { const w = points.map((p) => Math.min(...cents.map((c) => d2(p, c)))); cents.push(points[rng.weighted(w)].slice()); } return cents; }
export function kmedoids(points, init, dist = manhattan, maxIter = 30) { let med = init.slice(), labels; for (let it = 0; it < maxIter; it++) { labels = assign(points, med.map((i) => points[i]), dist); let changed = false; for (let j = 0; j < med.length; j++) { const mem = labels.map((l, i) => (l === j ? i : -1)).filter((i) => i >= 0); let best = med[j], bc = Infinity; for (const c of mem) { const cost = sum(mem.map((i) => dist(points[i], points[c]))); if (cost < bc) { bc = cost; best = c; } } if (best !== med[j]) { med[j] = best; changed = true; } } if (!changed) break; } return { medoids: med, labels }; }
export function silhouette(points, labels) { const n = points.length, k = Math.max(...labels) + 1; if (k < 2) return 0; let tot = 0; for (let i = 0; i < n; i++) { const s = new Array(k).fill(0), c = new Array(k).fill(0); for (let j = 0; j < n; j++) if (i !== j) { s[labels[j]] += euclid(points[i], points[j]); c[labels[j]]++; } const a = c[labels[i]] ? s[labels[i]] / c[labels[i]] : 0; let b = Infinity; for (let j = 0; j < k; j++) if (j !== labels[i] && c[j]) b = Math.min(b, s[j] / c[j]); tot += b === Infinity ? 0 : (b - a) / Math.max(a, b || 1e-9); } return tot / n; }
export function calinskiHarabasz(points, labels, cents) { const n = points.length, k = cents.length, g = points[0].map((_, d) => mean(points.map((p) => p[d]))), cnt = new Array(k).fill(0); labels.forEach((l) => cnt[l]++); const between = sum(cents.map((c, j) => cnt[j] * d2(c, g))), within = inertia(points, labels, cents); return within ? (between / (k - 1)) / (within / (n - k)) : 0; }
export function daviesBouldin(points, labels, cents) { const k = cents.length, s = new Array(k).fill(0), c = new Array(k).fill(0); points.forEach((p, i) => { s[labels[i]] += euclid(p, cents[labels[i]]); c[labels[i]]++; }); const sc = s.map((v, j) => (c[j] ? v / c[j] : 0)); let tot = 0; for (let i = 0; i < k; i++) { let m = 0; for (let j = 0; j < k; j++) if (i !== j) m = Math.max(m, (sc[i] + sc[j]) / (euclid(cents[i], cents[j]) || 1e-9)); tot += m; } return tot / k; }

// ---- density clustering ----
export function dbscan(points, eps, minPts) { const n = points.length, labels = new Array(n).fill(-2), kind = new Array(n).fill('noise'); const nb = (i) => { const r = []; for (let j = 0; j < n; j++) if (euclid(points[i], points[j]) <= eps) r.push(j); return r; }; let c = -1; for (let i = 0; i < n; i++) { if (labels[i] !== -2) continue; const N = nb(i); if (N.length < minPts) { labels[i] = -1; continue; } c++; labels[i] = c; kind[i] = 'core'; const q = N.slice(); for (let h = 0; h < q.length; h++) { const j = q[h]; if (labels[j] === -1) { labels[j] = c; kind[j] = 'border'; } if (labels[j] !== -2) continue; labels[j] = c; const N2 = nb(j); if (N2.length >= minPts) { kind[j] = 'core'; for (const x of N2) if (!q.includes(x)) q.push(x); } else kind[j] = 'border'; } } return { labels, kind, clusters: c + 1 }; }
export function meanShift(points, bw, iters = 30) { const modes = points.map((p) => p.slice()); for (let it = 0; it < iters; it++) for (let i = 0; i < modes.length; i++) { let sw = 0; const s = new Array(modes[i].length).fill(0); for (const p of points) { const w = Math.exp(-d2(modes[i], p) / (2 * bw * bw)); sw += w; for (let d = 0; d < s.length; d++) s[d] += w * p[d]; } modes[i] = s.map((v) => v / sw); } const cents = [], labels = []; for (const m of modes) { let j = cents.findIndex((c) => euclid(c, m) < bw / 2); if (j < 0) { cents.push(m); j = cents.length - 1; } labels.push(j); } return { cents, labels }; }

// ---- agglomerative ----
export function agglomerative(points, linkage = 'single') { let clusters = points.map((p, i) => [i]); const merges = []; const dist = (A, B) => { if (linkage === 'ward') { const ca = A[0].length === undefined ? null : null; const ma = points[0].map((_, d) => mean(A.map((i) => points[i][d]))), mb = points[0].map((_, d) => mean(B.map((i) => points[i][d]))); return (A.length * B.length) / (A.length + B.length) * d2(ma, mb); } let best = linkage === 'single' ? Infinity : -Infinity; for (const i of A) for (const j of B) { const d = euclid(points[i], points[j]); best = linkage === 'single' ? Math.min(best, d) : Math.max(best, d); } return best; }; while (clusters.length > 1) { let bi = 0, bj = 1, bd = Infinity; for (let i = 0; i < clusters.length; i++) for (let j = i + 1; j < clusters.length; j++) { const d = dist(clusters[i], clusters[j]); if (d < bd) { bd = d; bi = i; bj = j; } } merges.push({ a: clusters[bi], b: clusters[bj], d: bd }); const m = clusters[bi].concat(clusters[bj]); clusters = clusters.filter((_, i) => i !== bi && i !== bj); clusters.push(m); } return merges; }
export function cutTree(merges, n, k) { let clusters = Array.from({ length: n }, (_, i) => [i]); for (const m of merges) { if (clusters.length <= k) break; clusters = clusters.filter((c) => c !== m.a && c !== m.b && !(c.length === m.a.length && c.every((v, i) => v === m.a[i])) && !(c.length === m.b.length && c.every((v, i) => v === m.b[i]))); clusters.push(m.a.concat(m.b)); } const labels = new Array(n); clusters.forEach((c, j) => c.forEach((i) => (labels[i] = j))); return labels; }

// ---- Gaussian mixtures by EM (2D, full covariance) ----
export function gauss2(p, mu, cov) { const det = cov[0][0] * cov[1][1] - cov[0][1] * cov[1][0]; if (det <= 1e-12) return 0; const dx = p[0] - mu[0], dy = p[1] - mu[1], q = (dx * dx * cov[1][1] - 2 * dx * dy * cov[0][1] + dy * dy * cov[0][0]) / det; return Math.exp(-0.5 * q) / (2 * Math.PI * Math.sqrt(det)); }
export function emStep(points, comps) { const n = points.length, k = comps.length, resp = points.map((p) => { const w = comps.map((c) => c.w * gauss2(p, c.mu, c.cov)), t = sum(w) || 1e-300; return w.map((x) => x / t); });
  const next = comps.map((c, j) => { const nj = sum(resp.map((r) => r[j])) || 1e-9, mu = [sum(points.map((p, i) => resp[i][j] * p[0])) / nj, sum(points.map((p, i) => resp[i][j] * p[1])) / nj]; let a = 0, b = 0, d = 0; points.forEach((p, i) => { const dx = p[0] - mu[0], dy = p[1] - mu[1]; a += resp[i][j] * dx * dx; b += resp[i][j] * dx * dy; d += resp[i][j] * dy * dy; }); return { w: nj / n, mu, cov: [[a / nj + 1e-4, b / nj], [b / nj, d / nj + 1e-4]] }; });
  return { comps: next, resp, ll: logLik(points, comps) }; }
export function logLik(points, comps) { let ll = 0; for (const p of points) ll += Math.log(sum(comps.map((c) => c.w * gauss2(p, c.mu, c.cov))) || 1e-300); return ll; }

// ---- principal components: symmetric eigen decomposition by Jacobi rotations ----
export function covMatrix(X) { const n = X.length, d = X[0].length, mu = X[0].map((_, j) => mean(X.map((r) => r[j]))), C = Array.from({ length: d }, () => new Array(d).fill(0)); for (const r of X) for (let i = 0; i < d; i++) for (let j = 0; j < d; j++) C[i][j] += (r[i] - mu[i]) * (r[j] - mu[j]); for (let i = 0; i < d; i++) for (let j = 0; j < d; j++) C[i][j] /= n - 1; return { C, mu }; }
export function eigSym(A, sweeps = 60) { const n = A.length, a = A.map((r) => r.slice()), V = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 1 : 0))); for (let s = 0; s < sweeps; s++) { let off = 0; for (let p = 0; p < n; p++) for (let q = p + 1; q < n; q++) off += a[p][q] * a[p][q]; if (off < 1e-18) break; for (let p = 0; p < n; p++) for (let q = p + 1; q < n; q++) { if (Math.abs(a[p][q]) < 1e-15) continue; const th = (a[q][q] - a[p][p]) / (2 * a[p][q]), t = Math.sign(th || 1) / (Math.abs(th) + Math.sqrt(th * th + 1)), c = 1 / Math.sqrt(t * t + 1), sn = t * c; for (let k = 0; k < n; k++) { const x = a[k][p], y = a[k][q]; a[k][p] = c * x - sn * y; a[k][q] = sn * x + c * y; } for (let k = 0; k < n; k++) { const x = a[p][k], y = a[q][k]; a[p][k] = c * x - sn * y; a[q][k] = sn * x + c * y; } for (let k = 0; k < n; k++) { const x = V[k][p], y = V[k][q]; V[k][p] = c * x - sn * y; V[k][q] = sn * x + c * y; } } } const order = a.map((r, i) => [r[i], i]).sort((x, y) => y[0] - x[0]); return { values: order.map((o) => o[0]), vectors: order.map((o) => V.map((r) => r[o[1]])) }; }
export function pca(X) { const { C, mu } = covMatrix(X), e = eigSym(C), tot = sum(e.values.map((v) => Math.max(0, v))); return { mu, values: e.values, vectors: e.vectors, explained: e.values.map((v) => Math.max(0, v) / tot), project: (r, k) => e.vectors.slice(0, k).map((v) => v.reduce((s, c, j) => s + c * (r[j] - mu[j]), 0)) }; }
export function powerIteration(A, iters = 200) { let v = A.map((_, i) => 1 / (i + 1)); let lam = 0; for (let it = 0; it < iters; it++) { const w = A.map((r) => r.reduce((s, x, j) => s + x * v[j], 0)), n = Math.hypot(...w) || 1; v = w.map((x) => x / n); lam = v.reduce((s, x, i) => s + x * A[i].reduce((t, y, j) => t + y * v[j], 0), 0); } return { value: lam, vector: v }; }
